// GENERATED by worker/scripts/build-policy-content.mjs from policies/privacy.html and policies/terms.html; do not edit.
// The main text is the tracked policy text unchanged; the shell is the Worker's (.65). `npm run check:policies` fails when stale.
const PRIVACY = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify — Privacy Policy</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\" aria-current=\"page\">Privacy Policy</a><a href=\"/terms\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Privacy Policy</h1>\n<p class=\"meta\">Olympus Verify and the Olympus guild site · last updated 1 October 2026</p>\n\n<p>Olympus Verify is a private bot run by the volunteer staff of the World of Warcraft guild &ldquo;Olympus&rdquo;. It\nserves the Olympus Discord server and the Olympus channels in Asmongold's Discord server, and it is not offered to the\npublic or installed anywhere else. It exists to prove that a Discord account and an in-game character belong to the\nsame person, so guild channels can be opened to guild members without an officer checking every name by hand.</p>\n\n<h2>What it stores</h2>\n<p>Only what that check needs: your Discord user ID and display name; your BattleTag and Battle.net account ID, if you\nchoose to link one (kept for 29 days from your last Battle.net sign-in and then deleted, as Blizzard's developer terms\nrequire &mdash; sign in with Battle.net again to keep them; linking is optional and nothing depends on it); the characters you verify, with where each stands (code confirmed, invite queued, sent or refused,\njoined or left) and when; the in-game guild roster as the officers' addon exports it &mdash; each member's character name,\nrank, level, class, public and officer notes and last-online time, and the date the name first appeared &mdash; kept as\ndated snapshots (where the officers have switched on the guild note, the public note the bot has the addon write when you\njoin is <code>D:</code> followed by your Discord user ID, and every later export carries it); and a dated log of actions\ntaken (role granted, role removed, application approved or denied, a character unbound, a ban), each entry naming who\nacted, whom or what it concerned and the fixed details that action records (a denial or ban reason as the officer typed\nit; for an unbind, the account the character was bound to before), so officers can answer &ldquo;why did this\nhappen&rdquo;. It also keeps your Discord username and display name, as Discord reports them, for the characters you have\nlinked.</p>\n\n<h2>The guild site</h2>\n<p>The Olympus registration site (guild.roachcouncil.com, and olympus.roachcouncil.com once it moves there; the old\naddress then forwards to the new one) signs you in with Discord and checks one thing about your\nservers: whether you are a member of Asmongold's Discord server. For that it asks Discord for your identity and your\nmembership in that one server. It stores your Discord user ID, username, display name, nickname and avatar in that\nserver, when your Discord account was created and when you joined that server; what you enter &mdash; your application\n(your first choice and up to two backup roles, your answers, and the professions you plan to take if you name any),\nthe times of the week you usually play (kept as hours of the week in UTC, with your time zone), your votes on the\nvoting board, the people you write in for a role and why, the friends you list, and the character names you reserved\n&mdash; and when you signed in. It never receives your Discord password, your email address, your other servers or\nyour messages, and it keeps no Discord access token after you are signed in.</p>\n<p><strong>The voting board.</strong> Leadership roles are voted on, except those the guild's leadership chooses\nwithout a public vote (the site marks them); an application for only such roles is not shown on the board. If you\napply for a role that is voted on and tick the box that shows your application on the voting board, every member\nsigned in to the site can read it there, under each role you chose that is voted on then or later: your Discord display\nname and, as its picture, the game's own class icon for the class you gave (the site shows the game's icons, never your\nDiscord picture; the avatar reference Discord gave at sign-in stays stored with your account record, as said above),\nyour class, role and where you play from, which roles you chose (first choice or backup), how many NA and\nEU raid evenings a week you can make, and your answers to the four questions about your experience, why Olympus,\nleading people, and the loot argument. Your main character, professions, logs, references, voice chat, hours, weekly\nschedule and the last free-text box are never shown there. An application leaves the board when you withdraw it or\nonce the leadership has decided it. Votes on the board and people written in for a role are counted and seen only by\nthe site's administrators; nobody else, including the applicants and the people written in, sees how anyone voted or\nany counts. Someone you write in is told the role the next time they sign in, never by whom.</p>\n\n<h2>The community pages</h2>\n<p>The site has community pages that the guild's staff switch on one at a time; a page that is off shows nothing and\ntakes no new entries or actions, while what it already holds stays in your copy, keeps the lifetime stated below, is\ncleaned up on the same schedule, can still be erased on request, and stays in the dated log as before. Each stores only\nwhat you enter there or\nwhat the officers record, under your Discord user ID. Nothing on these pages changes your Discord roles, your guild\nmembership or your access by itself: the officers decide those, and this software keeps the records.</p>\n<p><strong>Member directory and crafting offers.</strong> You may list, for other guild members, a main character, a\nraid role, up to four professions with a skill level, up to ten alts you claim, and up to fifty crafting offers. They are\nshown to members signed in to the site whose own character the officers' roster export confirms, only while you keep them\nlisted and remain such a member yourself; other members see you by your display name and a random reference, never your\nDiscord user ID. A character name you enter is a label until it matches the officers' record of your characters; a name\nbound to another account is refused. Officers may confirm or reject a claimed alt. A profile whose owner is no longer a\nconfirmed member stops being shown at once and is deleted, with everything under it, by the scheduled cleanup from\nthirty days later.</p>\n<p><strong>Calendar and attendance.</strong> Organizers (the site's administrators and the members named as organizers)\ncreate events: a title, details, start, duration, capacity and the roles wanted. You answer yes, tentative or no with a\ncharacter and a raid role, and you can give or change that answer only before the event starts, while the calendar is on\nand you are a confirmed member; your answer, display name and character are visible to confirmed members looking at the\nevent, and it holds a place only while you remain one. After an event started an organizer may record\nattendance (present, possibly late or having left early; absent; excused; or unknown). Attendance never feeds roles,\neligibility or any penalty. An event, its answers, attendance and history are deleted by the scheduled cleanup from\nthirty days after it ends (a cancellation brings that forward).</p>\n<p><strong>Trial reviews.</strong> Officers may record a trial about your account: when it began, when its review is\ndue, whether it was extended, and how it concluded (passed, or ended with a fixed reason). You can read your own trial's\nstatus and dates on the site, never the sponsor or the officers involved. A trial is kept thirty days after it concluded,\nor after its review was due if it never did; from that moment no page shows it and no new copy contains it, and the row\nis deleted in the scheduled cleanup (bounded batches, so it may take more than one run).</p>\n<p><strong>Restriction cases, the watch-list and the return review.</strong> Officers may record a case about a Discord\naccount &mdash; a ban, a removal for conduct, or a removal for unpaid guild dues &mdash; with its dates, review and appeal\ndecisions, and may record that the same account signed in again after the case was set. A case may carry a watch-list:\nthe names and in-game identifiers of that account's characters, copied from the officers' own record, so the officers can\nsee when another account later holds one of them. Watch-list rows are kept for at most twelve months per member (one\nperiod, which an officer may renew with a fixed reason), never longer than their case. These are staff records and review\nevidence only: nothing here bans, removes or recognizes anyone by itself. A removal case ends at its expiry (at most two\nyears), a ban case when an officer resolves it; a resolved case is kept thirty days. Past those moments no page shows the\ncase and no new copy contains it.</p>\n<p><strong>Departure review items.</strong> When a character bound to your account leaves or is removed from the\nin-game guild, a review item (the character, whether it left or was removed, the date) exists for thirty days so an\nofficer can acknowledge it or open a case from it. Nothing is decided by the item itself.</p>\n<p><strong>Guild dues (the contribution ledger).</strong> When the officers switch it on, the site keeps a ledger of the\nweekly guild dues in in-game copper: your weeks (eligible or exempt, due, paid, acknowledged), the payments the officers\nrecord (amount, date and source; the payer name as written in the game is for officers only), and your acknowledgements\nof a notice. The site shows you a mail reference to put in the subject of the in-game mail so an officer can match it to\nyou; it is a matching aid, not proof of payment &mdash; the officer records the payment. Nothing is sent to you or taken\nfrom you by this software; an officer may record that you were removed in game for unpaid dues, which is a record, not an\naction. Ledger records are kept for the period the officers set when they switch it on (between one day and ten years,\nfixed when each record is written). Past its period a week is answered to no one; past its period a recorded payment's\nprivate details (its source identifier, the payer name as written, who recorded it) become unavailable at once and its\nunused remainder can never pay a later week, with one narrow exception kept on purpose: while a payment already paid a\nweek that is itself still within its period, the minimum the accounting needs stays with that week: the payment's kind\n(an officer's entry, a mail, a bank log), the amount it paid that week and the part already retired, its date and status,\nand which week it paid; nothing more, so the week's paid state is never falsified, and it goes when the week goes.</p>\n\n<p>It does not store your Blizzard password or your Discord password &mdash; it never sees either. It does not read or\nstore your Discord messages or DMs, your email address, your IP address, your real-money payment details (it has no\npayments), or anything about your activity outside this one guild. The in-game copper the guild dues ledger records, when\nthe officers switch it on, is described under the community pages. In the game, the officers' addon reads the\nverification codes whispered or mailed to an officer's character, the game's own guild join and leave messages, the guild\nroster and the result of each invite it sends. A companion program on that officer's computer reads the game client's chat\nlog file (which holds whatever chat that client logs) and the addon's saved data, and forwards to the bot only what it\nextracts from them: the code, the character and guild names, the invite outcomes, the roster export, whether that officer\nis in the world, and a timing measurement of the log file itself. By its code nothing else is sent, and the chat log stays\non that officer's computer; this describes the software as written, not a guarantee about the game client.</p>\n\n<p><strong>If you are banned from verifying</strong>, the bot keeps your Discord user ID and the reason; the\ncharacters bound to that account stay bound to it. Nothing derived from your BattleTag is kept beyond the 29 days.</p>\n<p><strong>Discord's own copy.</strong> Linking sets a &ldquo;Battle.net linked&rdquo; mark on your Discord account's\nlinked-role record for this bot. Links made since the bot's update of early October 2026 write the word\n&ldquo;linked&rdquo; there instead of your BattleTag; a BattleTag copied into that record by an earlier link stays\nthere, under your Discord account, until you link again (which overwrites it) or remove the connection in Discord's\nsettings (Connections). The bot holds nothing that\ncould clear it for you, and <code>/verify-status</code> reminds everyone who ever linked of this.</p>\n\n<h2>Where it goes</h2>\n<p>Data lives in a Cloudflare D1 database owned by the guild's officers, in Cloudflare's infrastructure, together with\nthe site's files and the Worker's logs (Workers Logs keep what the bot prints: fixed error categories and bounded status\ncodes, never messages, tokens, codes, tags or addresses). A working copy of the invite queue, the addon's saved data and\nthe game's chat log sit on the computer of the officer who sends the invites. The bot talks to Discord as part of its\nordinary work: it reads members' roles and nicknames, grants and removes the Guild Member role, sets nicknames where that\nis switched on, bans where an officer orders it, writes a short reason into Discord's own audit log for those changes,\nrefreshes the Discord usernames and display names of linked members, re-checks a signed-in member's server membership\nabout hourly after a save, and posts the notices and staff messages described below; Discord keeps its own records of all\nthat under its terms. Blizzard is involved only in the Battle.net sign-in you initiate. Nothing is sold or used for\nadvertising, training or analytics, and there are no third-party trackers on this page; beyond what this page describes,\nnothing is shared.</p>\n\n<h2>Who can see it</h2>\n<p>Guild officers, through the bot's own commands and their in-game addon, can see which Discord account a character\nbelongs to, its Discord username and display name, and how its verification went. The same lookup tells them whether\nyou applied on the guild site, for which role and how far it got, and the character names you reserved. The site's\nadministrators can see everything you entered on the site. Other members can see that you have signed up there (when\nthey search for someone to write in or list as a friend), if you put a leadership application on the voting board, what\nthe board shows, and what you list for them on the community pages (your directory profile and crafting offers, your\ncalendar answers), as those sections say; nothing else you entered. Everyone else in the server sees only what the bot\nshows in public: your server nickname, where the staff have switched that on, which it then sets to your character's\nname when you are admitted; and the short notices in the server's bot notices channel (#bot-announcements in the Olympus\nserver; #olympus-notices once the bot serves Asmongold's server) that mention you when your access changes. The Terms of\nService list which notices those are; anything you might not want read out only says there is an update, and\n<code>/verify-status</code> shows the detail to you alone. The bot's log channel is private to staff.</p>\n<p>The site's administrators also use the staff pages of the community features: the directory's claims review,\ntrials, cases and their watch-lists, departure items, the dues ledger with the payer names and sources of recorded\npayments, the private request cases, and two staff views that change nothing: a coverage report (the latest roster export\nnext to what the bot and the site already know about each bound account) and the counts behind the officer digest. Every\nchange a staff member makes is recorded in the dated log under their Discord user ID; reading is not. Once a day the bot\nmay post to a staff channel how many things wait for an officer, as counts only, never a name or an ID. A staff\nrank-planning page keeps its draft in that administrator's own browser and stores nothing on the server; that browser\ncopy outlives signing out and any deletion on the server until the administrator clears their browser's data.</p>\n\n<h2>Getting rid of it</h2>\n<p>Ask any officer, or open a ticket in the server's help channel. For the bot, an officer unbinds your characters: each\ncharacter row is marked unbound and loses its in-game identifier, your open code requests and queue entries are\ncancelled, and your Guild Member role follows the next roster export. The bot has no delete command: your member row\n(your Discord user ID and, if you were banned from verifying, the ban and its reason), the unbound character rows and the\ndated log stay, and the officers handle a request to erase the bot's data about you by hand, in the database, as a\nseparate request; unbinding alone is not erasure. Leaving the Discord server does none of this by itself. The guild's\nroster history is kept: it holds character names, ranks, notes and dates, and where the bot wrote your Discord user ID\ninto a character's public note the exported note carries it; the history is not scrubbed of it.</p>\n<p>The same goes for the guild site: ask any officer, or open a ticket, and the site's administrators delete\neverything the site holds about you at once &mdash; your application, votes, write-ins, friends list and reserved names,\nthe votes others cast on your application, and your account there. On request they also remove what other members\nentered about you: write-ins naming you, friends-list entries, and references to you in their applications, with any\nnote written about you; this works even if you never signed in to the site. If your registration was permanently\ndenied, your account row is kept, emptied of your names, picture and account dates, with your Discord user ID, the\ndenial, its reason, when and by whom it was decided, and the row's operational state (whether you were in the server when\nlast checked and when that was, and the sign-in counter the site uses to end old sessions; the sign-in dates set to the\ndecision's moment), so the same account cannot simply sign up again.</p>\n<p><strong>If you can no longer reach Discord</strong>, the site has a private request form, when the staff have\nswitched it on, that needs no sign-in: your browser makes a case number and a secret case code, you write what you ask\nfor (and, if you wish, a hint who you are or which character), and the administrators answer in that case. The case\nnumber is stored as it is: it names the case in the staff pages (their addresses included) and in the dated log, and the\nadministrators open a case by its number through their own signed-in staff session, without your code. The code is stored\nonly as a hash, so nobody can read it back; it travels only in your requests, never in a link, and it is what lets you,\nand only you, read and continue the case. The form keeps no email address and no\nIP address, and a case proves nothing about who owns an account: the administrators verify that in the conversation\nbefore acting through the site's own tools, and a case by itself exports, deletes or changes nothing. A case is kept for\nthe period the form states when you open it, counted from its last activity: a message from you, or a staff change while\nthe case is open, extends the deadline under that same period (reading never does), closing the case pins it, and a later\nchange to a closed case may update its activity time without extending it. Past the deadline the case is answered to no\none (judged by the database's own clock) and deleted in the scheduled cleanup, which works in bounded batches; nothing\nrecalls a copy you already took.</p>\n<p>The same deletion removes everything the community pages hold about you: your profile and offers, your event answers\nand attendance, your trials, your departure items, and your dues records (your weeks, the payments matched to you and your\nacknowledgements). What remains is this, and only this: the dated log of actions (each entry's name, who acted, whom or\nwhat it concerned and its recorded details, as described under what it stores, with your Discord user ID as the subject or\nas the actor); an active restriction case with its watch-list and the member period those rows\nrun under, because the case is about the account and not about the site (an inactive case is deleted with your account;\nthe period, whose dated renewal note the officers may read, survives only while one of your cases is still unresolved, and\nan ended period admits no new watch-list row and renews nothing); and the bot's own rows (your characters, your queue\nentries and your member row), which the officers handle as described above (unbinding through the bot; erasure by hand on\nrequest). The\ndeparture review's cleanup keeps one shared bookmark of where its last scan of the guild's departures stopped (a departure\ntime and a character name key, never a Discord account ID); it is replaced on the next run and cleared when a run reaches\nthe end, and it is not about any one account. The officer digest keeps its own working state (the channel, the message it\nposted, a nonce, the day, a lease and the outcome), about no account. Private request cases are not account records at\nall: they are keyed by their number; you reach yours only with its code, the administrators reach them through their\nadmitted staff session; so deleting your site data does not touch them, and closing or deleting a case touches nothing\nelse. An administrator whose own account is erased is removed as the reviewer,\napprover, recorder or setter from every record the site keeps such a pointer in; the dated log keeps its actor IDs as\nsaid, Discord keeps its own messages, and free text someone else wrote that happens to name them is not searched.</p>\n<p>Where a record has a stated lifetime &mdash; a trial, a case, a departure item, a dues record, a private request case\n&mdash; no page shows it and no new copy contains it from the moment the lifetime ends, judged by the database's own clock\ninside each read, with the one exception stated above for the dues ledger (the minimum accounting of an expired payment,\nits kind, the amount it paid, the part retired, its date and status and which week, stays with a week that is itself\nstill within its period); the physical deletion follows in the scheduled cleanup, which works in bounded batches, so it may take\nseveral runs, and waits while the Worker's schema check fails. Profiles and events follow their own rule, stated above,\nnot a deadline inside each read: a profile stops being shown as soon as its owner no longer qualifies and is deleted by\nthat cleanup thirty days later; an event, its answers and attendance remain as the calendar shows them until that cleanup\ndeletes them thirty days after it ended. None of this recalls a copy already downloaded, the officers' local working\ncopies, or what Discord holds in its own messages and logs.</p>\n\n<h2>Your copy</h2>\n<p>While signed in to the site you can download a copy of what it and the bot hold about your Discord account, curated\nfor you (the site's address followed by <code>/api/me/export</code>). It lists your account; your application, with the people you\nnamed as references by the names you chose, not their accounts; your votes and friends by the labels you chose; your\nreserved names; the bot's view of you (whether you are banned from verifying, whether a Battle.net link is current\n&mdash; never the BattleTag &mdash;, the characters bound to you, your code requests without any code, your place in the\ninvite queue); the dated actions that name your account, shown as their time and action name only (the earliest\nthousand, with a way to continue); and every community page's records about you. It leaves out staff notes and reasons,\nstaff identities, the raw roster snapshots and the private details of recorded payments; your own labels and free text are\ncopied as you wrote them, so they can name other people. Each copy, and each continuation of the dated actions, is read in\none go at the moment it states, and the Worker allows about five copies an hour (a limit it keeps in memory, so\napproximate). A private request case is not in it: cases are keyed by their number, not by any account, and are read only\nwith their code.</p>\n\n<h2>Contact</h2>\n<p>The guild's Discord staff, in the server's help channel. This bot is run by volunteers, not a company.</p>\n\n<p class=\"meta related\">See also the <a href=\"/terms\">Terms of Service</a>.</p>\n</main>\n</body>\n</html>\n";
const TERMS = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify — Terms of Service</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\">Privacy Policy</a><a href=\"/terms\" aria-current=\"page\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Terms of Service</h1>\n<p class=\"meta\">Olympus Verify and the Olympus guild site · last updated 1 October 2026</p>\n\n<p>Olympus Verify and the Olympus guild site are provided free, as-is, with no warranty, by the volunteer staff of one\nWorld of Warcraft guild, for the use of that guild's members and applicants. They are not a commercial service, and the\nbot is not available for installation elsewhere.</p>\n\n<h2>Using it</h2>\n<p>By verifying a character you confirm it is yours. Claiming someone else's character,\nsharing verification codes, or using the bot to gain access you were not given is grounds for losing guild and Discord\naccess.</p>\n\n<h2>The guild site</h2>\n<p>By applying you confirm that what you wrote is true and that the account is yours. Joke, troll and abusive\napplications are permanently denied, and so is voting under several accounts. A leadership application goes on the\nvoting board, where members can read it and vote on it, only when you tick the box that allows it; you can withdraw it\nat any time. Applying (first choice or backup), voting, writing someone in and entering a reserved name are requests\nand opinions, not promises: the guild's leadership decides roles and invitations.</p>\n<p><strong>The community pages.</strong> What you list in the directory or offer as crafting is yours to change or\nwithdraw at any time while the page is on; a calendar answer can be given or changed until the event starts; a character\nname you enter is a claim until it matches the officers' record.\nThe records the officers keep about you there &mdash; trials, restriction cases and their watch-lists, departure items,\nthe dues ledger &mdash; are the guild's staff records; they do not by themselves grant or remove access, roles or\nmembership. Guild dues are the guild's own arrangement: the ledger records what the officers confirm was paid, the mail\nreference is a matching aid and not proof of payment, and any question about a payment or a week is for the officers.\nThe site's administrators have a rank-planning page whose drafts stay in their own browser; a draft is a proposal, never a\nchange in the guild.</p>\n<p>The site is a free, non-commercial fan project. It is not affiliated with or endorsed by Blizzard Entertainment. It\nuses interface artwork and icons from the World of Warcraft game client, which remain the property of Blizzard\nEntertainment, Inc., and two interface fonts taken from the same client (Friz Quadrata, whose embedded notice names\nInternational Typeface Corporation, 1997, and Morpheus, whose embedded notice names Kiwi Media/Design, Eric Oehler, 1996),\nreproduced with those notices intact; nothing here claims their ownership or grants any right to redistribute them, and\nthe site's own code licence does not extend to them. World of Warcraft and Blizzard Entertainment are trademarks or\nregistered trademarks of Blizzard Entertainment, Inc.</p>\n\n<h2>How it tells you about your access</h2>\n<p>The bot never sends direct messages. When something changes about your own access &mdash; your character is on the\nguild roster, you are back in the invite queue, or a seat was freed &mdash; it posts a short notice in the server's bot\nnotices channel (#bot-announcements in the Olympus server; #olympus-notices once the bot serves Asmongold's server) and\nmentions you, so you get an ordinary notification. Only the welcome (your character is on the guild roster) is said in\nfull; every other notice, including being back in the queue or a freed seat, and anything you might not want read out in\nfront of the server, such as an invite that was declined or refused or an application that was decided, only says there\nis an update, and <code>/verify-status</code> shows you the detail privately. In that\nchannel it posts nothing else &mdash; no announcements, no marketing &mdash; and it is rate-limited; whether a notice\nreaches you depends on the channel's permissions and on Discord. The bot also writes to the staff's own channels: its log\nlines, review cards and, where the officers switch it on, a daily digest of how many things wait for them, as counts only.\nYou can mute the notices channel at any time; <code>/verify-status</code> always shows the same information on request.</p>\n\n<h2>Availability</h2>\n<p>Staff may change, pause or retire the bot at any time. Guild membership itself is decided by officers, not by this\nsoftware; the bot only reflects the in-game guild roster.</p>\n\n<p class=\"meta related\">See also the <a href=\"/privacy\">Privacy Policy</a>.</p>\n</main>\n</body>\n</html>\n";

/** The canonical policy document a path names, or null. Aliases keep every address that ever served or redirected one. */
export function policyDocument(path: string): string | null {
  if (["/privacy", "/privacy-policy", "/privacy.html"].includes(path)) return PRIVACY;
  if (["/terms", "/tos", "/terms-of-service", "/terms.html"].includes(path)) return TERMS;
  return null;
}
